const items = $input.all();
const rows = items.map(i => i.json);
const dateStr = new Date().toISOString().split('T')[0];

let totalCaptures = 0;
let totalEntities = 0;
let totalAlerts = 0;

for (const row of rows) {
  totalCaptures += parseInt(row.captures_count) || 0;
  totalEntities += parseInt(row.entities_count) || 0;
  totalAlerts += parseInt(row.alerts_count) || 0;
}

let md = `# Weekly Project Summary - ${dateStr}\n\n`;
md += `**${rows.length} projects tracked** | ${totalCaptures} captures | ${totalEntities} new entities | ${totalAlerts} alerts\n\n`;

if (rows.length === 0) {
  md += '_No projects found._\n';
} else {
  md += '| Project | Slug | Captures | New Entities | Alerts |\n';
  md += '|---------|------|----------|--------------|--------|\n';
  for (const row of rows) {
    const name = (row.display_name || row.slug || 'Unknown').replace(/\|/g, '\\|');
    const slug = (row.slug || '').replace(/\|/g, '\\|');
    const captures = row.captures_count || 0;
    const entities = row.entities_count || 0;
    const alerts = row.alerts_count || 0;
    const alertFlag = parseInt(alerts) > 0 ? ` ⚠️` : '';
    md += `| ${name} | ${slug} | ${captures} | ${entities} | ${alerts}${alertFlag} |\n`;
  }
  md += `| **Total** | | **${totalCaptures}** | **${totalEntities}** | **${totalAlerts}** |\n`;
}

return [{ json: { markdown: md, dateStr } }];
